var engagements = pgTable("engagements", {
  id: integer("id").primaryKey().generatedByDefaultAsIdentity(),
  /** The paid Business Health Check behind it; null for an engagement opened directly (0016). */
  businessCheckId: integer("businessCheckId").unique().references(() => businessChecks.id),
  businessId: integer("businessId").references(() => businesses.id),
  /** What kind of engagement it is (0016): it decides the timeline and the starting content (shared/engagementTypes.ts). */
  type: engagementsTypeEnum("type").default("business_review").notNull(),
  /** The service bought, a product id from shared/products.ts, for an Assessment, Done for You or Monthly Service (0018). */
  service: varchar("service", { length: 64 }),
  /** Day 0 of a dated engagement (Digital marketing). */
  startedOn: date("startedOn"),
  /** The client contact for an engagement opened directly, when there is no Business Health Check to name them. */
  contactName: varchar("contactName", { length: 200 }),
  contactEmail: varchar("contactEmail", { length: 320 }),
  /** Opened before it was paid (0020): the room shows only the first fee to pay until a fee is paid, online or by hand. */
  opensOnPayment: boolean("opensOnPayment").default(false).notNull(),
  /** Paid in arrears (0023, R74): each month's fee falls due 30 days after its month, from the kickoff (startedOn). */
  paidInArrears: boolean("paidInArrears").default(false).notNull(),
  /** The confirmed Current State Assessment payment that started it. */
  paymentRequestId: integer("paymentRequestId").references(() => paymentRequests.id),
  stage: engagementsStageEnum("stage").default("setting_up").notNull(),
  /** The problem area chosen at the end of the assessment (shared/businessSupport.ts PROBLEM_AREAS number). */
  problemArea: integer("problemArea"),
  subProblem: varchar("subProblem", { length: 255 }),
  /** In the owner's words: exactly one problem per fix. */
  problemStatement: text("problemStatement"),
  assessmentStartedAt: timestamp("assessmentStartedAt", { withTimezone: true }),
  fixStartedAt: timestamp("fixStartedAt", { withTimezone: true }),
  closedAt: timestamp("closedAt", { withTimezone: true }),
  createdAt: timestamp("createdAt", { withTimezone: true }).defaultNow().notNull(),
  updatedAt: timestamp("updatedAt", { withTimezone: true }).defaultNow().$onUpdate(() => sql`now()`).notNull()
}, (table2) => [index("engagements_business_idx").on(table2.businessId), index("engagements_stage_idx").on(table2.stage)]);
