function healthReport(settings = ENV) {
  const ok = settings.missingSettings.length === 0;
  return {
    status: ok ? 200 : 503,
    body: { ok, service: "ipfactory-sme", build: settings.buildCommit || null, ...ok ? {} : { missing: [...settings.missingSettings] } }
  };
}

